    s_in_l = np.zeros(s["n"])
    np.add.at(s_in_l, s["rows"], jv)
    s_tot_l = s_out_l + s_in_l
    s_safe_l = np.where(s_tot_l > 0, s_tot_l, 1.0)
    jv_cr = jv / np.sqrt(s_safe_l[s["rows"]] * s_safe_l[s["cols"]])
    OPS[sname] = dict(beta=jv, crofts=jv_cr)
